import {tripLogo,spanishLabel} from './branding.mjs';
import {requireSession,signOut} from './auth.mjs';
import {sharedSnapshot} from './shared-trip.mjs';
import {collectParticipants,assignParticipant} from './participants.mjs';
import {pickupGroups,pickupsHTML} from './pickups.mjs';
import {shareTrip,sharedFeedback,sharedPanel} from './shared-ui.mjs';
import {exportHTML,exportExcel,exportFilename} from './trip-export.mjs';
import {participantRole,setTravelMode,saveVehicleAssignments,vehicleForPerson,vehicleKey,validateAssignments} from './transport.mjs';
import {rosterRows,resetWithRoster,cachedRoster} from './roster.mjs';
import {extractDocument} from './document-reader.mjs';
import {csvRecords,normalize,pendingItems} from './core.mjs';
import {syncDetectedParticipants,removeParticipant} from './document-model.mjs';
import {renderDashboard} from './trip-dashboard.mjs';
import {createDocumentFeatures} from './document-ui.mjs';
const sessionUser=await requireSession();if(!sessionUser.admin){location.replace('/me');await new Promise(()=>{});}
const $=s=>document.querySelector(s),uid=()=>crypto.randomUUID(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rosterTarget=null;
let dashboardFilter='all';
let db,state={trips:[]},selected=null,globalView='trips',tab='overview',submitAction=null,importKind='people',folderTarget=null,toastTimer;
const dbReady=new Promise((resolve,reject)=>{const r=indexedDB.open('equip-viatges-v0',1);r.onupgradeneeded=()=>{r.result.createObjectStore('data');r.result.createObjectStore('folders');};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)});
async function read(store,key){await dbReady;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function write(store,key,value){await dbReady;return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function remove(store,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function persist(){collectParticipants(state);await write('data','state',state);render();const t=trip();if(t?.shared){try{await shareTrip(t);await write('data','state',state)}catch(e){render();toast("Cambios guardados en el navegador. "+e.message)}}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5500)}
function fail(e){console.error(e);toast(e.name==='QuotaExceededError'?"Almacenamiento lleno. Prueba con una carpeta más pequeña.":e.message||"No se ha podido completar la operación.")}
const trip=()=>state.trips.find(t=>t.id===selected),date=s=>s?new Date(s+'T12:00:00').toLocaleDateString("es-ES",{day:'numeric',month:'short',year:'numeric'}):"Fechas por confirmar";
const badge=s=>`<span class="status ${['Comprat','Fet','Reservat'].includes(s)?'done':s==='No cal'?'neutral':''}">${esc(s==='Comprat'?'OK · Comprado':spanishLabel(s||'Pendent'))}</span>`;
const sport=s=>`<span class="pill ${s==='Ciclisme'?'cycle':''}">${s==='Ciclisme'?'↗':'❄'} ${esc(spanishLabel(s))}</span>`;
const empty=(title,description,button='')=>`<div class="empty"><div class="empty-icon">▤</div><h3>${title}</h3><p>${description}</p>${button}</div>`;
function render(){const t=trip();$('#allTrips').classList.toggle('active',globalView==='trips');$('#allParticipants').classList.toggle('active',globalView==='participants');if(!t&&globalView==='participants'){$('#crumb').textContent="Participantes";renderParticipants();return;}$('#crumb').textContent=t?t.name:"Viajes";if(!t){selected=null;renderHome();return}renderTrip(t)}
function renderParticipants(){
 collectParticipants(state);
 $('#app').innerHTML=`<div class="page-head"><div><h1>Participantes</h1><p>Una ficha por persona. Asígnala a los viajes con el desplegable.</p></div><div class="actions"><button class="button secondary" data-action="import-directory">Importar Excel</button><button class="button" data-action="new-directory-person">＋ Participante</button></div></div>${!state.trips.length?"<div class=\"notice\">Crea un viaje para poder asignarle participantes. <button class=\"text-button\" data-action=\"new-trip\">＋ Crear viaje</button></div>":''}${state.participants.length?`<label class="field directory-search">Buscar participante<input id="participantSearch" type="search" placeholder="Nombre o email" autocomplete="off"></label><div class="table-wrap"><table><thead><tr><th>PARTICIPANTE</th><th>VIAJES ASIGNADOS</th><th>ASIGNAR A UN VIAJE</th><th></th></tr></thead><tbody>${state.participants.map(p=>{const assigned=state.trips.filter(t=>t.people.some(x=>x.participantId===p.id)),available=state.trips.filter(t=>!assigned.includes(t));return `<tr data-directory-row data-search="${esc((p.name+' '+p.email).toLowerCase())}"><td><strong>${esc(p.name)}</strong><small>${esc(p.email||"Email personal pendiente")}</small><small>${esc(spanishLabel(p.role))}</small></td><td><div class="assigned-trips">${assigned.length?assigned.map(t=>`<button class="trip-assignment" data-action="open-trip" data-id="${esc(t.id)}">${esc(t.name)} ↗</button>`).join(''):"<span class=\"muted\">Sin viaje asignado</span>"}</div></td><td><label class="field"><span class="visually-hidden">Asignar ${esc(p.name)} a un viaje</span><select data-assign-participant="${esc(p.id)}" ${available.length?'':'disabled'}><option value="">${available.length?"Selecciona un viaje…":"Ningún viaje disponible"}</option>${available.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}${t.start?' · '+date(t.start):''}</option>`).join('')}</select></label></td><td><button class="edit-button" data-action="edit-directory-person" data-id="${esc(p.id)}">Editar datos</button></td></tr>`}).join('')}</tbody></table></div><p id="directoryEmpty" hidden>No se ha encontrado ningún participante.</p><p class="small muted">Asignar una persona a otro viaje conserva las asignaciones anteriores. Los vuelos, vehículos y notas se gestionan dentro de cada viaje.</p>`:empty("Añade los participantes del equipo","Importa un Excel o crea una ficha. Después selecciona el viaje de cada persona.")}`;
}
function directoryPersonForm(id,tripId=''){collectParticipants(state);const person=state.participants?.find(p=>p.id===id)||{};modal(id?"Datos del participante":"Nuevo participante",`<div class="form-grid">${field("Nombre y apellidos",'name',person.name,'text',true,true)}${field('Email personal','email',person.email,'email')}${field("Teléfono",'phone',person.phone,'tel')}${select('Rol','role',person.role||'Esportista',['Esportista','Tècnic','Fisio','Altres'])}${field('Origen','origin',person.origin)}${!id&&state.trips.length?select("Asignar al viaje",'tripId',tripId,[['',"Asignar más adelante"],...state.trips.map(t=>[t.id,t.name])]):''}</div><p class="small muted">Los datos personales se actualizan en los viajes asignados. Los vuelos y las recogidas se conservan.</p>`,async data=>{const assignTo=data.tripId||'';delete data.tripId;if(assignTo&&!state.trips.some(t=>t.id===assignTo))throw Error("El viaje seleccionado ya no existe.");data.email=data.email.toLowerCase();if(data.email&&state.participants.some(p=>p.id!==id&&p.email.toLowerCase()===data.email))throw Error("Ya existe un participante con este email.");const changed=[];if(id){Object.assign(person,data);for(const t of state.trips){const members=t.people.filter(p=>p.participantId===id);for(const p of members)Object.assign(p,data);if(members.length)changed.push(t);}}else{const entry={id:uid(),...data};state.participants.push(entry);if(assignTo){const assigned=assignParticipant(state,entry.id,assignTo);changed.push(assigned);if(selected===assignTo)tab='people';}}await persist();for(const t of changed)await syncDirectoryTrip(t);toast("Datos personales guardados.");});}
async function syncDirectoryTrip(t){if(!t.shared)return;try{await shareTrip(t)}catch(e){toast("Datos locals guardadas. "+e.message)}await write('data','state',state);}
function renderHome(){$('#app').innerHTML=`<div class="page-head"><div><h1>Viajes</h1><p>Selecciona un viaje para gestionarlo.</p></div><button class="button" data-action="new-trip">＋ Nuevo viaje</button></div>${state.trips.length?`<div class="grid">${state.trips.map(t=>`<button class="trip-card" data-action="open-trip" data-id="${t.id}"><div class="trip-top">${tripLogo(t)}${sport(t.sport)}<span>↗</span></div><div class="trip-content"><h3>${esc(t.name)}</h3><p>${esc(t.destination||"Destino pendiente")} · ${date(t.start)}</p></div><div class="trip-footer"><span>${t.people.length} participantes · ${t.vehicles.length} vehículos</span></div></button>`).join('')}</div>`:empty("Empieza con un viaje","Créalo, añade participantes y selecciona la carpeta.")}<details class="simple-details"><summary>Copias y datos</summary><p class="small muted">La gestión se guarda en este navegador. Los itinerarios compartidos se guardan en el servidor.</p><div class="actions"><button class="button secondary" data-action="backup">Exportar copia</button><button class="button secondary" data-action="restore">Restaurar copia</button></div></details>`}
function renderTrip(t){const transportTab=['vehicles','pickups'].includes(tab);$('#app').innerHTML=`<button class="back" data-action="home">← Viajes</button><div class="page-head"><div>${tripLogo(t)}<h1>${esc(t.name)}</h1><p>${esc(t.destination||"Destino pendiente")} · ${date(t.start)}${t.end?' — '+date(t.end):''}</p></div><div class="actions"><button class="button" data-action="share-trip">${t.shared?"Actualizar portal":"Compartir viaje"}</button><button class="button secondary" data-action="export-trip">↓ Resumen</button><details class="more-menu"><summary class="button secondary">Más ···</summary><div class="more-menu-items"><button data-action="edit-trip">Editar viaje</button><button data-action="access-settings">Acceso de los deportistas</button><button data-action="shared-feedback">Confirmaciones</button><a href="/me" target="_blank" rel="noopener">Portal del deportista ↗</a><button data-action="import-roster">Cambiar Excel de participantes</button><button data-action="reset-roster">Reiniciar con el Excel</button><button data-action="backup">Exportar copia de seguridad</button></div></details></div></div>${t.sharedError?`<div class="notice">${esc(t.sharedError)} <button class="button secondary" data-action="resolve-sharing">Revisar versiones</button></div>`:''}<nav class="tabs" aria-label="Secciones del viaje">${[['overview',"Preparación"],['details',"Datos del viaje"],['people',"Participantes"],['files',"Documentos y vuelos"],['vehicles',"Vehículos y recogidas"]].map(([key,label])=>`<button class="tab ${(key==='vehicles'?transportTab:tab===key)?'active':''}" data-action="tab" data-id="${key}" aria-current="${(key==='vehicles'?transportTab:tab===key)?'page':'false'}">${label}</button>`).join('')}</nav><div id="tripContent">${tab==='overview'?overview(t):tab==='details'?tripDetails(t):tab==='people'?people(t):transportTab?`<div class="transport-switch"><button class="button ${tab==='pickups'?'secondary':''}" data-action="tab" data-id="vehicles">Vehículos</button><button class="button ${tab==='vehicles'?'secondary':''}" data-action="tab" data-id="pickups">Recogidas</button></div>${tab==='pickups'?pickupsHTML(t,esc):vehicles(t)}`:files(t)}</div>`}
function folderPanel(t){return `<div class="folder-panel"><div class="folder-icon">▣</div><div><h3>${esc(t.folder?.name||"Vincula la carpeta del viaje")}</h3><p>${t.folder?`${t.files.length} documentos · ${t.folder.mode==='handle'?"Lectura con permiso":"Copia local en el navegador"}`:"Selecciona una carpeta de tu ordenador para tener los documentos a mano."}</p>${t.folder?`<p>Última lectura: ${new Date(t.folder.updated).toLocaleString("es-ES")}</p>`:''}</div><div class="actions">${t.folder?"<button class=\"button lime\" data-action=\"refresh-folder\">↻ Actualizar</button>":''}<button class="button ${t.folder?'secondary':'lime'}" data-action="link-folder">${t.folder?"Cambiar carpeta":'Vincular carpeta'}</button></div></div>`}
function rosterPanel(t){return `<div class="notice"><strong>1. Excel de participantes → 2. Carpeta de documentos</strong><p>${t.rosterSource?esc(t.rosterSource)+' · '+t.people.length+" participantes":"Importa el Excel con la lista oficial. Después selecciona la carpeta para asociar las reservas."}</p><div class="actions"><button class="button" data-action="import-roster">Importar Excel de participantes</button><button class="button secondary" data-action="reset-roster">Reiniciar con el Excel importado</button></div></div>`}
function rosterPreview(t,rows,source){modal("Reiniciar con "+rows.length+" participantes",`<p>Se sustituirá la lista de este viaje por los participantes de <strong>${esc(source)}</strong>.</p><div class="notice">Se borrarán las asociaciones, los estados de billete y check-in y el vínculo con la carpeta. Después podrás seleccionar la carpeta de nuevo. Los documentos originales no se modifican.</div><div class="csv-preview"><ul>${rows.map(p=>`<li>${esc(p.name)}${p.role?' · '+esc(p.role):''}</li>`).join('')}</ul></div>`,async()=>{const draft=resetWithRoster(t,rows,source),next={...state,trips:state.trips.map(x=>x.id===t.id?draft:x)};await new Promise((resolve,reject)=>{const tx=db.transaction(['data','folders'],'readwrite');tx.objectStore('data').put(t,'before-roster-reset:'+t.id);tx.objectStore('data').put(next,'state');tx.objectStore('folders').delete(t.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});state=next;tab='overview';dashboardFilter='all';render();if(draft.shared){try{await shareTrip(draft);await write('data','state',state)}catch(e){toast("Reinicio local guardado; falta actualizar el espacio compartido. "+e.message);return}}toast(rows.length+" participantes preparados. Ahora selecciona la carpeta de documentos.")},"Reiniciar e incorporar los "+rows.length+" participantes")}
function tripDetails(t){return `<div class="section-head"><div><h2>Datos del viaje</h2><p>Completa las fechas, el alojamiento y el contacto de coordinación.</p></div><button class="button" data-action="edit-trip">Editar datos</button></div><div class="admin-detail-grid">${[["Viaje",[["Nombre",t.name],["Equipo",t.sport],["Destino",t.destination],["Salida",t.start?date(t.start):''],['Tornada',t.end?date(t.end):'']]],["Alojamiento y contacto",[["Alojamiento",t.hotel],["Dirección completa · ADAMS",t.hotelAddress],['Responsable',t.coordinator],["Teléfono de coordinación",t.phone]]]].map(([title,rows])=>`<section class="panel"><h3>${title}</h3><dl class="detail-list">${rows.map(([label,value])=>`<div><dt>${spanishLabel(label)}</dt><dd>${value?esc(value):"<span class=\"admin-missing\">Pendiente de completar</span>"}</dd></div>`).join('')}</dl></section>`).join('')}</div><section class="panel"><h3>Notas internas de coordinación</h3><p style="white-space:pre-wrap">${esc(t.notes||"Sin notas internas.")}</p><p class="small muted">Las indicaciones personales de cada deportista se editan en su ficha.</p></section>`}
function overview(t){
 const missing=[['destination','destino'],['start','salida'],['end','vuelta'],['hotel','alojamiento'],['coordinator','responsable'],['phone','teléfono']].filter(([key])=>!t[key]).map(([,label])=>label);
 const emails=t.people.filter(p=>!p.email).length,pending=documents.pending(t);
 const transportMissing=t.people.filter(p=>['Anada','Tornada'].some(d=>{const v=vehicleForPerson(t,p,d);return !v||!v.driver||!v.phone||!v.pickupLocation||!v.pickupTime})).length;
 const steps=[
 ["Datos del viaje",missing.length?'Falta: '+missing.join(', '):"Fechas, alojamiento y contacto completados.",!missing.length,'tab','details',"Completar datos"],
 ["Participantes",t.people.length?`${t.people.length} participantes · ${emails?emails+" sin email personal":"emails informados"}`:"Añade participantes manualmente, desde la lista general o con un Excel.",!!t.people.length&&!emails,'tab','people',t.people.length?"Revisar participantes":"Añadir participantes"],
 ["Documentos y vuelos",t.files.length?`${t.files.length} documentos · ${pending} pendientes de revisión`:"Selecciona la carpeta con billetes y reservas.",!!t.files.length&&!pending,'tab','files',t.files.length?"Revisar documentos":"Añadir documentos"],
 ["Vehículos y recogidas",t.people.length?`${t.vehicles.length} vehículos · ${transportMissing} participantes con transporte o contacto incompleto`:"Indica los conductores, teléfonos, puntos y horas de recogida.",!!t.people.length&&!transportMissing,'tab','vehicles',"Organizar transportes"],
 ["Acceso de los deportistas",t.shared?"Viaje compartido. Consulta los accesos y las confirmaciones.":"Revisa los emails personales antes de compartir el viaje.",!!t.shared,'access-settings','',"Revisar acceso"]
 ];
 return `<section class="admin-preparation"><div class="section-head"><div><h2>Prepara el viaje</h2><p>Completa cada apartado. Puedes volver y corregir los datos en cualquier momento.</p></div><span class="pill">${steps.filter(s=>s[2]).length} de ${steps.length} apartados completados</span></div><div class="preparation-steps">${steps.map(([title,description,done,action,id,label],i)=>`<section class="preparation-step ${done?'is-complete':''}"><span class="step-number">${done?'✓':i+1}</span><div><h3>${title}</h3><p>${esc(description)}</p></div><button class="button secondary" data-action="${action}" data-id="${id}">${label}</button></section>`).join('')}</div></section>${t.people.length?`<div class="section-head"><h2>Seguimiento de participantes</h2><button class="button secondary" data-action="shared-feedback">Ver confirmaciones</button></div>${renderDashboard(t,dashboardFilter,esc)}`:''}`;
}
function people(t){return `<div class="section-head"><h2>${t.people.length} participantes</h2><div class="actions"><button class="button" data-action="new-person">＋ Añadir participante</button><button class="button secondary" data-action="directory">Asignar participante existente</button><button class="button secondary" data-action="import-roster">${t.people.length?"Cambiar lista de Excel":'Importar Excel'}</button></div></div>${t.people.length?`<div class="table-wrap"><table class="compact-people"><thead><tr><th>PARTICIPANTE</th><th>BILLETE</th><th>CHECK-IN</th><th>VEHÍCULO</th><th></th></tr></thead><tbody>${t.people.map(p=>`<tr><td><button class="person-name text-button" data-action="participant-itinerary" data-id="${p.id}">${esc(p.name)}</button><small>${esc(spanishLabel(participantRole(p.role)))} · ${esc(spanishLabel(p.travelMode||'Avió'))}</small><small class="${p.email?'':'admin-missing'}">${esc(p.email||'Falta email personal')}</small></td><td>${badge(p.ticket)}</td><td><button class="text-button" data-action="person-checkin" data-id="${p.id}" aria-label="Check-in de ${esc(p.name)}">${badge(p.checkin)} ↗</button></td><td>${['Anada','Tornada'].map(d=>{const v=vehicleForPerson(t,p,d);return `<small>${spanishLabel(d)}: ${esc(v?.name||"Sin asignar")}</small>`}).join('')}</td><td><button class="edit-button" data-action="edit-person" data-id="${p.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`:empty("Añade los participantes del viaje","Crea una ficha manualmente, asigna una persona existente o importa un Excel.")}<p class="muted small">Pulsa el nombre para ver el itinerario completo.</p>`}
function vehicles(t){return `<div class="section-head"><h2>Transportes</h2><div class="actions"><details class="simple-details inline-details"><summary>Importar vehículos</summary><button class="text-button" data-action="template" data-id="vehicles">Plantilla CSV</button><button class="text-button" data-action="import" data-id="vehicles">Importar CSV</button></details><button class="button" data-action="new-vehicle">＋ Vehículo</button></div></div>${t.vehicles.length?`<div class="grid">${t.vehicles.map(v=>{const ps=t.people.filter(p=>p[vehicleKey(v.direction)]===v.id);return `<section class="panel"><div class="section-head" style="margin-top:0"><h3>${esc(v.name)}</h3><span class="pill">${esc(spanishLabel(v.direction))}</span></div><dl class="detail-list"><div><dt>Conductor</dt><dd>${esc(v.driver||"Por asignar")}</dd></div><div><dt>Teléfono</dt><dd>${esc(v.phone||"Sin indicar")}</dd></div><div><dt>Salida</dt><dd>${esc(v.origin||"Por confirmar")}</dd></div><div><dt>Hora</dt><dd>${esc(v.departure||"Por confirmar")}</dd></div><div><dt>Plazas para pasajeros</dt><dd>${v.seats||"Sin indicar"}</dd></div><div><dt>Aparcamiento</dt><dd>${esc(v.parking||"Sin indicar")}</dd></div></dl><p class="small"><strong>Pasajeros asignados:</strong> ${ps.length?ps.map(p=>esc(p.name)).join(', '):"Ninguno"}</p>${v.passengers?`<p class="small"><strong>Pasajeros indicados en el CSV:</strong> ${esc(v.passengers)}</p>`:''}${v.pickupLocation||v.pickupTime?`<p><strong>Recogida:</strong> ${esc(v.pickupLocation||"Lugar pendiente")} · ${esc(v.pickupTime||"Hora pendiente")}</p>`:''}${v.notes?`<p class="small muted">${esc(v.notes)}</p>`:''}<button class="edit-button" data-action="edit-vehicle" data-id="${v.id}">Editar transporte</button></section>`}).join('')}</div>`:empty("Cada trayecto, bien organizado","Crea un vehículo por trayecto: ida o vuelta. Indica el conductor, la salida, la hora y las plazas.","<button class=\"button\" data-action=\"new-vehicle\">＋ Añadir vehículo</button>")}`}
function files(t){return `<section class="panel import-guide"><h2>Importa la información de los documentos</h2><p><strong>1.</strong> Importa el Excel de participantes. <strong>2.</strong> Selecciona la carpeta. <strong>3.</strong> Revisa y confirma los datos detectados.</p><p class="muted">Los PDF, Excel, CSV e imágenes compatibles pueden aportar vuelos, horarios, localizadores y emails de compra. Completa el alojamiento, los conductores y las recogidas en sus apartados.</p>${!t.people.length?"<button class=\"button\" data-action=\"import-roster\">Importar participantes</button>":''}</section>${folderPanel(t)}${documents.panel(t)}<div class="notice">${t.folder?.mode==='handle'?"La carpeta se vuelve a leer con «Actualizar».":"Vuelve a seleccionar la carpeta para actualizar la copia local."} Los archivos nuevos se leen automáticamente. Los documentos se leen en tu ordenador.</div>${t.files.length?`<div class="table-wrap"><table><thead><tr><th>DOCUMENTO</th><th>LECTURA / PERSONAS</th><th>TAMAÑO</th><th></th></tr></thead><tbody>${t.files.map((f,i)=>`<tr><td class="file-path"><strong>${esc(f.name)}</strong><small>${esc(f.path)}</small></td><td>${documents.status(t,f)}</td><td class="nowrap">${formatSize(f.size)}</td><td><div class="row-links"><button class="edit-button" data-action="review-document" data-id="${esc(f.path)}">Revisar / asociar</button><button class="edit-button" data-action="download-file" data-id="${i}">Descargar</button>${/\.(csv|tsv)$/i.test(f.name)?`<button class="edit-button" data-action="import-file" data-id="${i}">Importar datos</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty("Los documentos del viaje","Vincula una carpeta. Leeremos los nombres y trayectos para proponerte a quién corresponde cada documento.")}`}

function formatSize(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB'}
function field(label,key,value='',type='text',full=false,required=false){return `<label class="field ${full?'full':''}">${label}<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`}
function select(label,key,value,options){return `<label class="field">${label}<select name="${key}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(spanishLabel(l))}</option>`}).join('')}</select></label>`}
function notes(value){return `<label class="field full">Notas<textarea name="notes">${esc(value||'')}</textarea></label>`}
function modal(title,html,fn,label='Guardar'){$('#modal').classList.remove('document-modal');submitAction=fn;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#submitModal').textContent=label;$('#modal').showModal()}
function tripForm(edit=false){const t=edit?trip():{};modal(edit?"Editar viaje":"Nuevo viaje",`<div class="form-grid"><h3 class="form-section-title">Destino y fechas</h3>${field("Nombre del viaje",'name',t.name,'text',true,true)}${select("Equipo",'sport',t.sport||'Esquí',['Esquí','Ciclisme'])}${field("Destino",'destination',t.destination)}${field("Fecha de salida",'start',t.start,'date')}${field("Fecha de vuelta",'end',t.end,'date')}<h3 class="form-section-title">Contacto de coordinación</h3>${field('Responsable','coordinator',t.coordinator)}${field("Teléfono",'phone',t.phone,'tel')}<h3 class="form-section-title">Alojamiento</h3>${field("Nombre del alojamiento / información existente",'hotel',t.hotel,'text',true)}<label class="field full">Dirección completa · para ADAMS<textarea name="hotelAddress" placeholder="Calle y número, código postal, localidad y país">${esc(t.hotelAddress||'')}</textarea></label><label class="field full">Notas internas de coordinación<textarea name="notes">${esc(t.notes||'')}</textarea></label></div>`,async data=>{if(data.start&&data.end&&data.end<data.start)throw Error("La vuelta no puede ser anterior a la salida.");if(edit)Object.assign(t,data);else{const n={...data,id:uid(),rosterMode:'excel',people:[],vehicles:[],files:[],folder:null};state.trips.push(n);selected=n.id;globalView='trips';tab='overview'}await persist();toast(edit?"Viaje actualizado":"Viaje creado. Ya puedes vincular una carpeta.")})}
function personForm(id){const t=trip();if(!id){directoryPersonForm(undefined,t.id);return}const p=t.people.find(p=>p.id===id)||{};modal(id?"Editar participante":"Nuevo participante",`<div class="form-grid">${field("Nombre y apellidos",'name',p.name,'text',true,true)}${select("Rol en el equipo",'role',participantRole(p.role),['Esportista','Tècnic','Fisio','Altres'])}${select("Cómo viaja",'travelMode',p.travelMode||'Avió',['Avió','Cotxe','Per decidir'])}${field("Email personal · acceso al viaje",'email',p.email,'email')}${field("Teléfono",'phone',p.phone,'tel')}${field('Origen','origin',p.origin)}${select("Billete",'ticket',p.ticket||'Pendent',['Pendent','Comprat','No cal'])}${select('Check-in','checkin',p.checkin||'Pendent',['Pendent','Fet','No cal'])}${field("Llegada · día, hora y lugar",'arrival',p.arrival,'text',true)}${select("Vehículo asignado",'vehicle',p.vehicle||'',[['',"Sin asignar"],...t.vehicles.filter(v=>v.direction!=='Tornada').map(v=>[v.id,`${v.name} · ${v.direction}`])])}${select("Vehículo de vuelta",'returnVehicle',p.returnVehicle||'',[['',"Sin asignar"],...t.vehicles.filter(v=>v.direction==='Tornada').map(v=>[v.id,v.name])])}${field("Recogida · persona y lugar",'pickup',p.pickup)}${field("Aparcamiento",'parking',p.parking,'text',true)}${notes(p.notes)}</div>${id?documents.journeySummary(t,p)+documents.personSummary(t,p)+`<button type="button" class="button secondary" data-action="participant-itinerary" data-id="${p.id}">Ver itinerario individual</button>`:''}${id?'<button type="button" class="text-button error" data-action="delete-person" data-id="'+id+"\">Eliminar participante</button>":''}`,async data=>{if(id){const check=structuredClone(t);Object.assign(check.people.find(x=>x.id===id),data);validateAssignments(check);if(data.ticket!==p.ticket)p.ticketSource='manual';const mode=data.travelMode;delete data.travelMode;Object.assign(p,data);setTravelMode(p,mode)}else t.people.push({...data,id:uid()});await persist();toast("Participante guardado")})}
function vehicleForm(id){const t=trip(),v=t.vehicles.find(v=>v.id===id)||{};modal(id?"Editar transporte":"Nuevo transporte",`<div class="form-grid">${field("Vehículo · nom o matrícula",'name',v.name,'text',false,true)}${select("Trayecto",'direction',v.direction||'Anada',['Anada','Tornada'])}${select("Conductor · participante",'driverId',v.driverId||'',[['',"Conductor externo"],...t.people.map(p=>[p.id,p.name+' · '+participantRole(p.role)])])}${field("Nombre del conductor externo",'driver',v.driver)}${field("Teléfono del conductor",'phone',v.phone,'tel')}${field("Punto de salida",'origin',v.origin)}${field("Día y hora de salida",'departure',v.departure)}${field("Plazas para pasajeros (sin conductor)",'seats',v.seats||'','number')}${field("Aparcamiento / reserva",'parking',v.parking)}${field("Aeropuerto / punto de recogida",'pickupLocation',v.pickupLocation)}${field("Hora de recogida",'pickupTime',v.pickupTime)}${field("Pasajeros indicados / anotaciones",'passengers',v.passengers,'text',true)}<fieldset class="field full"><legend>Asignar pasajeros a este vehículo</legend>${t.people.map(p=>`<label class="check-label"><input type="checkbox" name="passenger_${p.id}" ${p[vehicleKey(v.direction)]===v.id&&v.id?'checked':''}>${esc(p.name)} · ${esc(spanishLabel(participantRole(p.role)))}</label>`).join('')}</fieldset>${notes(v.notes)}</div><p class="small muted">Selecciona los pasajeros de este trayecto. El conductor viaja en coche y no ocupa plaza de pasajero. Las asignaciones de ida y vuelta son independientes.</p>${id?'<button type="button" class="text-button error" data-action="delete-vehicle" data-id="'+id+"\">Eliminar vehículo</button>":''}`,async data=>{data.seats=Number(data.seats)||0;const ids=Object.keys(data).filter(k=>k.startsWith('passenger_')).map(k=>k.slice(10));for(const k of Object.keys(data))if(k.startsWith('passenger_'))delete data[k];const draft=saveVehicleAssignments(t,{...data,id:id||uid()},ids);await saveTrip(draft);toast("Transporte y pasajeros asignados")})}
async function scan(handle){const out=[];async function walk(dir,prefix=''){for await(const [name,entry]of dir.entries()){if(name.startsWith('.'))continue;const path=prefix+name;if(entry.kind==='directory')await walk(entry,path+'/');else{if(out.length>=2000)throw Error("La carpeta supera los 2.000 archivos. Selecciona una carpeta específica del viaje.");const f=await entry.getFile();out.push({name,path,size:f.size,modified:f.lastModified})}}}await walk(handle);return out.sort((a,b)=>a.path.localeCompare(b.path))}
async function linkFolder(){const t=trip();if(!t.people.length){toast("Añade primero los participantes del viaje.");return}if(!window.showDirectoryPicker){folderTarget=t.id;$('#folderInput').click();return}try{const handle=await window.showDirectoryPicker({mode:'read'});toast('Llegint la carpeta…');const list=await scan(handle);await write('folders',t.id,{handle});t.folder={name:handle.name,mode:'handle',updated:Date.now()};t.files=list;await persist();await documents.analyze(t)}catch(e){if(e.name!=='AbortError'){if(e.name==='SecurityError'){folderTarget=t.id;$('#folderInput').click()}else fail(e)}}}
async function refreshFolder(){const t=trip();if(!t.folder||t.folder.mode!=='handle'){folderTarget=t.id;$('#folderInput').click();return}const saved=await read('folders',t.id);if(!saved?.handle){toast("Vuelve a seleccionar la carpeta para recuperar el acceso.");return linkFolder()}if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís de lectura a la carpeta.');toast("Actualitzant documentos…");const list=await scan(saved.handle);t.files=list;t.folder.updated=Date.now();await persist();await documents.analyze(t)}
async function localFile(t,index){const meta=t.files[index],saved=await read('folders',t.id);if(!saved)throw Error("Vuelve a vincular la carpeta para acceder a los documentos.");if(saved.handle){if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error("Es necesario autorizar la lectura del documento.");let h=saved.handle;const parts=meta.path.split('/');for(const part of parts.slice(0,-1))h=await h.getDirectoryHandle(part);return await(await h.getFileHandle(parts.at(-1))).getFile()}const f=saved.files?.find(f=>f.path===meta.path)?.file;if(!f)throw Error('Document no disponible. Actualitza la carpeta.');return f}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function template(kind){const content=kind==='people'?"Nombre;Telefon;Origen;Llegada;Billete;Check-in;Recogida;Aparcamiento;Notas\r\nPersona exemple;600000000;Girona;Divendres 14:30 - Aeroport;Pendiente;Pendiente;;;\r\n":"Vehículo;Conductor;Telefon;Origen;Hora;Trayecto;Places;Passatgers;Aparcamiento;Notas\r\nFurgoneta 1;Conductor exemple;600000000;Girona;Divendres 08:00;Anada;7;;Pendiente;Espai per al material\r\n";download(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}),`plantilla-${kind==='people'?'participants':'transports'}.csv`)}
function importPreview(text,kind){const records=csvRecords(text,kind),t=trip(),keys=Object.keys(records[0]);if(records.length>2000)throw Error("Importa un máximo de 2.000 filas cada vez.");modal(`Importar ${kind==='people'?'participants':'transports'}`,`<p>${records.length} fichas detectades. Revisa les datos abans de continuar.</p><div class="csv-preview table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${records.slice(0,20).map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${records.length>20?"<p class=\"small\">Se muestran las primeras 20 filas.</p>":''}<div class="notice">S’afegiran només noms nous. Si el nom ja existeix, se saltarà la fila per conservar les teves correccions. Els passatgers d’un CSV de transports es guarden com a anotació.</div>`,async()=>{const list=kind==='people'?t.people:t.vehicles,known=new Set(list.map(x=>normalize(x.name)));let added=0;for(const r of records){if(known.has(normalize(r.name)))continue;list.push({...r,id:uid(),...(kind==='people'?{vehicle:''}:{})});known.add(normalize(r.name));added++}await persist();toast(`${added} fichas afegides · ${records.length-added} duplicades omeses`)},'Confirmar importació')}
function backup(){download(new Blob([JSON.stringify({format:'equip-v0',exportedAt:new Date().toISOString(),trips:state.trips,participants:state.participants||[]},null,2)],{type:'application/json'}),'equip-viatges-copia.json');toast("Copia exportada. No incluye los documentos originales.")}
function versionSummary(snapshot){return `<dl class="detail-list">${[['Destino',snapshot.destination],['Fechas',[snapshot.start,snapshot.end].filter(Boolean).join(' — ')],['Equipo',spanishLabel(snapshot.sport)],['Alojamiento',snapshot.hotel],['Coordinación',[snapshot.coordinator,snapshot.phone].filter(Boolean).join(' · ')]].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value||'Pendiente')}</dd></div>`).join('')}</dl><h4>Participantes e itinerarios</h4><div class="version-comparison">${snapshot.people.map(p=>`<details><summary>${esc(p.name)} · ${esc(p.email||'Sin email')}</summary><p>${esc(spanishLabel(p.role))} · ${esc(spanishLabel(p.travelMode))}</p><p>Billete: ${esc(spanishLabel(p.ticket))} · Check-in: ${esc(spanishLabel(p.checkin))}</p>${(p.journeys||[]).map(j=>`<p>${esc(Object.entries(j).filter(([k,v])=>!['id','personId','documentId','fileIndex'].includes(k)&&typeof v==='string').map(([,v])=>spanishLabel(v)).join(' · '))}</p>`).join('')}${(p.transports||[]).map(v=>`<p>${esc(spanishLabel(v.direction))}: ${esc([v.name,v.driver,v.phone,v.origin,v.departure,v.pickupLocation,v.pickupTime].filter(Boolean).join(' · ')||'Transporte pendiente')}</p>`).join('')}<p>${esc(p.notes||'')}</p></details>`).join('')}</div>`;}
const handlers={
'resolve-sharing':async()=>{const t=trip(),remote=await sharedFeedback(t);if(!remote.trip){await shareTrip(t,{force:true});await write('data','state',state);render();toast('Viaje compartido.');return;}
 const local=sharedSnapshot(t),server=remote.trip.snapshot;
 modal('Revisar versiones del viaje',`<p>Revisa la información antes de sustituir la versión que ven los deportistas. Se guardará una copia de la versión compartida en este navegador.</p><div class="admin-detail-grid"><section class="panel"><h3>Este navegador</h3><p>${esc(local.name)} · ${local.people.length} participantes</p>${versionSummary(local)}</section><section class="panel"><h3>Portal compartido</h3><p>${esc(server.name)} · ${server.people.length} participantes</p><p>Actualizado: ${esc(new Date(remote.trip.updated_at).toLocaleString('es-ES'))}</p>${versionSummary(server)}</section></div>`,async()=>{await write('data','shared-backup:'+t.id+':'+remote.trip.revision,server);download(new Blob([JSON.stringify(server,null,2)],{type:'application/json'}),'copia-itinerario-compartido.json');await shareTrip(t,{force:true,expectedRevision:remote.trip.revision});await write('data','state',state);render();toast('Portal actualizado con la versión de este navegador.');},'Publicar la versión de este navegador');},

'new-directory-person':()=>directoryPersonForm(),'edit-directory-person':directoryPersonForm,'import-directory':()=>{rosterTarget='directory';$('#rosterInput').click()},'directory':()=>{selected=null;globalView='participants';render()},
'access-settings':()=>modal("Acceso de los deportistas",sharedPanel(trip(),esc).replaceAll('<button ', '<button type="button" '),async()=>{},"Cerrar"),'assign-pickup':index=>{const t=trip(),group=pickupGroups(t)[Number(index)];if(!group)return;const vs=t.vehicles.filter(v=>v.direction===group.direction);if(!vs.length){toast("Crea primero un vehículo de "+group.direction.toLowerCase()+'.');vehicleForm();return}modal("Asignar recogida · "+group.airport,`${select("Vehículo",'vehicleId',vs[0].id,vs.map(v=>[v.id,v.name+' · '+(v.seats||'?')+' places']))}<p>Selecciona les persones. Es conservaran els altres passatgers del vehículo.</p>${group.people.map(({person:p,vehicle:v})=>`<label class="check-label"><input type="checkbox" name="passenger_${p.id}" ${v?'':'checked'}>${esc(p.name)}${v?' · '+esc(v.name):''}</label>`).join('')}`,async data=>{const v=t.vehicles.find(v=>v.id===data.vehicleId),ids=[...new Set([...t.people.filter(p=>p[vehicleKey(v.direction)]===v.id).map(p=>p.id),...Object.keys(data).filter(k=>k.startsWith('passenger_')).map(k=>k.slice(10))])];await saveTrip(saveVehicleAssignments(t,v,ids));toast("Recogida assignada")},"Asignar passatgers")},
'share-trip':async()=>{const t=trip();try{await shareTrip(t,{force:true});await write('data','state',state);render();toast("Itinerarios guardados en el espacio compartido.")}catch(error){await write('data','state',state);render();if(t.sharedConflict)return handlers['resolve-sharing']();throw error;}},
'shared-feedback':async()=>{const t=trip(),data=await sharedFeedback(t);modal("Confirmaciones de los deportistas",data.trip?`<p>Última versió compartida: ${esc(new Date(data.trip.updated_at).toLocaleString("es-ES"))}</p><ul>${t.people.map(p=>{const f=data.feedback.find(f=>f.person_id===p.id);return `<li><strong>${esc(p.name)}</strong> · ${f?.seen_revision===data.trip.revision?"✓ Ha vist el viaje":"Pendiente de consultar"} · Check-in: ${esc(f?.checkin||p.checkin||'Pendent')}</li>`}).join('')}</ul>`:"<p>Comparte primero los itinerarios.</p>",async()=>{},"Cerrar")},'export-trip':()=>{const t=trip();modal("Descargar resumen del viaje",`<p>${t.people.length} participantes amb nom, rol, vols, furgo d’anada, furgo de tornada i notes.</p>${select('Format','format','html',[['html',"Resumen visual · HTML imprimible / desar com a PDF"],['xlsx','Excel · XLSX']])}<p class="small muted">El resum visual s’obre amb el navegador. Per tenir-lo en PDF, obre el fitxer i selecciona Imprimir → Desar com a PDF.</p>`,async data=>{if(data.format==='xlsx')download(new Blob([await exportExcel(t)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),exportFilename(t)+'.xlsx');else download(new Blob([exportHTML(t)],{type:'text/html;charset=utf-8'}),exportFilename(t)+'.html');toast("Resumen del viaje descargado")},"Descargar")},'participant-itinerary':id=>{const t=trip(),p=t.people.find(p=>p.id===id);if(!p)return;modal('Itinerari · '+p.name,`<p>${esc(t.name)} · ${esc(spanishLabel(participantRole(p.role)))} · ${esc(spanishLabel(p.travelMode||'Avió'))}</p>${documents.journeySummary(t,p)}${['Anada','Tornada'].map(direction=>{const v=vehicleForPerson(t,p,direction);return `<section class="panel"><h3>${direction} · transport</h3>${v?`<p><strong>${esc(v.name)}</strong>${v.driverId===p.id?' · Condueixes tu':''}</p><dl class="detail-list"><div><dt>Conductor</dt><dd>${esc(v.driver||"Por asignar")}</dd></div><div><dt>Teléfono</dt><dd>${esc(v.phone||'Pendent')}</dd></div><div><dt>Salida</dt><dd>${esc(v.origin||'Pendent')} · ${esc(v.departure||'Pendent')}</dd></div><div><dt>Recogida</dt><dd>${esc(v.pickupLocation||'Pendent')} · ${esc(v.pickupTime||'Pendent')}</dd></div></dl>`:"<p>Vehículo pendiente de asignar.</p>"}</section>`}).join('')}<section class="panel"><h3>Alojamiento</h3><p>${esc(t.hotel||"Pendiente de confirmar")}</p></section>${p.travelMode!=='Cotxe'?`<button type="button" class="button" data-action="person-checkin" data-id="${p.id}">Datos per al check-in</button>`:''}<p class="small muted">Vista de coordinación. Comparteix els itineraris perquè apareguin al portal personal dels deportistas autoritzats.</p>`,async()=>{},"Cerrar")},'import-roster':()=>{rosterTarget=trip().id;$('#rosterInput').click()},'reset-roster':()=>{const t=trip(),cached=cachedRoster(t);if(cached)rosterPreview(t,cached.rows,cached.source);else{rosterTarget=t.id;$('#rosterInput').click()}},'dashboard-filter':value=>{dashboardFilter=value;render()},'new-trip':()=>tripForm(),'edit-trip':()=>tripForm(true),'open-trip':id=>{globalView='trips';selected=id;tab='overview';render()},home:()=>{selected=null;globalView='trips';render()},tab:id=>{tab=id;render()},'new-person':()=>personForm(),'edit-person':personForm,'new-vehicle':()=>vehicleForm(),'edit-vehicle':vehicleForm,'link-folder':linkFolder,'refresh-folder':refreshFolder,template,import:kind=>{importKind=kind;$('#csvInput').click()},backup,restore:()=>{if(documents.isBusy()){toast("Detén la lectura antes de restaurar una copia.");return}$('#restoreInput').click()},
'download-file':async index=>{const t=trip(),f=await localFile(t,Number(index));download(f,t.files[index].name)},
'import-file':async index=>{const t=trip(),f=await localFile(t,Number(index)),text=await f.text();modal("Quines datos conté el fitxer?",`<div class="form-grid">${select("Tipus de fichas",'kind','people',[['people',"Participantes"],['vehicles',"Transportes"]])}</div>`,async data=>{setTimeout(()=>{try{importPreview(text,data.kind)}catch(e){fail(e)}},0)},"Revisar datos")},
'delete-person':id=>{if(!confirm("¿Quieres eliminar este participante?"))return;const t=trip();removeParticipant(t,id);$('#modal').close();return persist()},
'delete-vehicle':id=>{if(!confirm("¿Quieres eliminar este vehículo? Los participantes quedarán sin esta asignación."))return;const t=trip();t.vehicles=t.vehicles.filter(v=>v.id!==id);t.people.forEach(p=>{if(p.vehicle===id)p.vehicle='';if(p.returnVehicle===id)p.returnVehicle=''});$('#modal').close();return persist()}
};
async function saveTrip(draft){const next={...state,trips:state.trips.map(t=>t.id===draft.id?draft:t)};collectParticipants(next);await write('data','state',next);state=next;render();if(draft.shared){try{await shareTrip(draft);await write('data','state',state)}catch(e){render();toast("Canvis locals guardados. "+e.message)}}}
const documents=createDocumentFeatures({esc,field,select,modal,toast,read,persist,render,getTrip:trip,getState:()=>state,localFile,goToDocuments:()=>{tab='files';render()},goToParticipants:()=>{tab='people';render()},saveTrip});
Object.assign(handlers,documents.handlers);
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){if(documents.isBusy()&&!['home','open-trip','tab','stop-reading','download-file','backup'].includes(el.dataset.action)){toast("Espera a que termine la lectura o detenla antes de modificar los datos.");return}const fn=handlers[el.dataset.action];if(fn)Promise.resolve().then(()=>fn(el.dataset.id)).catch(fail)}});
$('#allParticipants').onclick=handlers.directory;$('#allTrips').onclick=handlers.home;$('#backup').onclick=backup;$('#restore').onclick=handlers.restore;$('#closeModal').onclick=$('#cancelModal').onclick=()=>$('#modal').close();
$('#modalForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(data))data[k]=data[k].trim();if('name'in data&&!data.name){toast("Indica un nombre.");return}$('#submitModal').disabled=true;try{await submitAction(data);$('#modal').close()}catch(e){fail(e)}finally{$('#submitModal').disabled=false}};
$('#rosterInput').onchange=async e=>{try{const file=e.target.files[0],t=state.trips.find(t=>t.id===rosterTarget);if(!file)return;const content=await extractDocument(file),rows=rosterRows(content.tables);if(rosterTarget==='directory'){modal("Importar participantes",`<p>${rows.length} persones detectades a ${esc(file.name)}.</p><p>S’afegiran les persones noves. Es conservaran les fichas amb el mateix email; els noms coincidents sense email quedaran pendientes d’afegir manualment.</p>`,async()=>{collectParticipants(state);let added=0,skipped=0;for(const row of rows){const email=String(row.email||'').trim().toLowerCase();if(state.participants.some(p=>email?p.email.toLowerCase()===email:normalize(p.name)===normalize(row.name))){skipped++;continue;}state.participants.push({...row,email,id:uid()});added++;}await persist();toast(`${added} participantes afegits · ${skipped} coincidencias omeses`);},'Importar');}else if(t)rosterPreview(t,rows,file.name)}catch(e){fail(e)}finally{e.target.value=''}};
$('#csvInput').onchange=async e=>{try{const f=e.target.files[0];if(f){if(f.size>5*1024*1024)throw Error("El CSV supera los 5 MB.");importPreview(await f.text(),importKind)}}catch(e){fail(e)}finally{e.target.value=''}};
$('#folderInput').onchange=async e=>{try{const fs=Array.from(e.target.files);if(!fs.length)return;const t=state.trips.find(t=>t.id===folderTarget);if(!t)return;if(fs.length>2000)throw Error("Selecciona una carpeta con menos de 2.000 archivos.");if(fs.reduce((n,f)=>n+f.size,0)>150*1024*1024)throw Error("La copia supera los 150 MB. Selecciona una carpeta más pequeña o utiliza Chrome para vincularla sin copiarla.");toast("Guardando los documentos en el navegador…");const files=fs.filter(f=>!f.webkitRelativePath.split('/').some(x=>x.startsWith('.'))).map(f=>({path:f.webkitRelativePath.split('/').slice(1).join('/'),file:f}));await write('folders',t.id,{files});t.folder={name:fs[0].webkitRelativePath.split('/')[0],mode:'copy',updated:Date.now()};t.files=files.map(({path,file:f})=>({path,name:f.name,size:f.size,modified:f.lastModified})).sort((a,b)=>a.path.localeCompare(b.path));await persist();await documents.analyze(t)}catch(e){fail(e)}finally{e.target.value=''}};
$('#restoreInput').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error("La copia es demasiado grande.");const data=JSON.parse(await f.text());if(data.format!=='equip-v0'||!Array.isArray(data.trips))throw Error("Este archivo no es una copia de Equipo.");for(const t of data.trips){if(typeof t.name!=='string'||!Array.isArray(t.people)||!Array.isArray(t.vehicles)||!t.people.every(p=>typeof p.name==='string')||!t.vehicles.every(v=>typeof v.name==='string'))throw Error("La copia contiene datos no válidos.")}modal("Restaurar copia",`<p>S’afegiran ${data.trips.length} viajes com a còpies noves. Els viajes actuals es conservaran.</p><p class="muted">Hauràs de tornar a vincular les carpetes dels documentos.</p>`,async()=>{collectParticipants(state);const restoredIds=new Map();for(const source of data.participants||[]){if(typeof source.name!=='string')continue;const match=source.email?state.participants.find(p=>p.email.toLowerCase()===String(source.email).toLowerCase()):null;const id=match?.id||uid();restoredIds.set(source.id,id);if(!match)state.participants.push({...source,id});}for(const source of data.trips){const t=structuredClone(source);t.id=uid();delete t.shared;t.name+=" (copia)";const ids=new Map();t.vehicles.forEach(v=>{const id=uid();ids.set(v.id,id);v.id=id});const personIds=new Map();t.people.forEach(p=>{const id=uid();personIds.set(p.id,id);p.id=id;p.participantId=restoredIds.get(p.participantId)||'';p.vehicle=ids.get(p.vehicle)||'';p.returnVehicle=ids.get(p.returnVehicle)||''});for(const r of Object.values(t.readings||{})){r.confirmed=(r.confirmed||[]).map(c=>({...c,personId:personIds.get(c.personId)})).filter(c=>c.personId);r.proposals=(r.proposals||[]).map(c=>({...c,personId:personIds.get(c.personId)||''}))}t.files=[];t.folder=null;state.trips.push(t)}await persist();toast("Copia restaurada")},'Restaurar')}catch(e){fail(e)}finally{e.target.value=''}};
try{state=await read('data','state')||{trips:[]};const upgraded=structuredClone(state);let created=0,linked=0,updated=0;for(const t of upgraded.trips){if(t.rosterMode!=='excel'){t.rosterMode='excel';updated++;}const result=syncDetectedParticipants(t);created+=result.added;linked+=result.linked;updated+=result.updated}const registryChanged=collectParticipants(upgraded);if(created||linked||updated||registryChanged){await write('data','state',upgraded);state=upgraded}state=upgraded;render();if(created)toast(`${created} participantes creats a partir dels documentos ja llegits.`)}catch(e){$('#app').innerHTML=empty("No se puede abrir el espacio local","Activa el almacenamiento del navegador y vuelve a cargar la página. Los datos no se pueden guardar en esta sesión.");fail(e)}

document.addEventListener('change',async e=>{const select=e.target.closest('[data-assign-participant]');if(!select||!select.value)return;select.disabled=true;try{const t=assignParticipant(state,select.dataset.assignParticipant,select.value);await persist();await syncDirectoryTrip(t);toast("Participante assignat a "+t.name);}catch(error){fail(error);render();}});
document.addEventListener('input',e=>{if(e.target.id!=='participantSearch')return;const query=e.target.value.toLowerCase().trim();let count=0;document.querySelectorAll('[data-directory-row]').forEach(row=>{row.hidden=!row.dataset.search.includes(query);if(!row.hidden)count++;});$('#directoryEmpty').hidden=!!count;});

document.querySelector('#adminSignOut').onclick=()=>signOut().catch(fail);
